import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import 'package:flutter/foundation.dart';import '../../../../../Core/Storage/Remote/api_error_handler.dart';import '../../../../../Core/Storage/Local/local_storage_keys.dart';import '../../../../../Core/Storage/Local/local_storage_service.dart';import '../../data/entities/login_model.dart';import '../../data/entities/register_model.dart';import '../../data/entities/user_data_model.dart';import '../../data/repositories/authentication.dart';import '../../data/sources/authentication_sources.dart';class AuthenticationRepoImpl extends AuthenticationRepo {  @override  Future<Either<Failure, UserDataModel>> loginByEmail(      LoginModel loginModel) async {    try {      final response = await AuthenticationSources.getUserDataByEmail(loginModel);      if (response.status && response.data != null) {        // Success case - return user data        return right(response.data!);      } else {        // Error with message from API        return left(ServerFailure(response.message));      }    } on DioException catch (e) {      // Handle specific status codes      if (e.response?.statusCode == 401) {        // Unauthorized - clear token and return specific error        await LocalStorageService.removeValue(LocalStorageKeys.token);        return left(ServerFailure.unauthorized());      }      // Handle other Dio errors      return left(ServerFailure.fromDioError(e));    } catch (e) {      // Handle generic errors      if (kDebugMode) {        print('Login error: ${e.toString()}');      }      return left(ServerFailure(e.toString()));    }  }  @override  Future<Either<Failure, bool>> registerByEmail(      RegisterModel registerModel) async {    try {      final response = await AuthenticationSources.createAccount(registerModel);      if (response.status) {        // Registration successful - return true        return right(true);      } else {        // Registration failed with message from API        return left(ServerFailure(response.message));      }    } on DioException catch (e) {      // Handle Dio errors      if (kDebugMode) {        print('Registration DioError: ${e.message}');      }      return left(ServerFailure.fromDioError(e));    } catch (e) {      // Handle generic errors      if (kDebugMode) {        print('Registration error: ${e.toString()}');      }      return left(ServerFailure(e.toString()));    }  }}